.product-card.is-selected { border-top-color: var(--ink); }
.product-image { width: clamp(54px, 12vw, 92px); aspect-ratio: 1; background: var(--surface); border-radius: 8px; overflow: hidden; }
.product-image img { width: 100%; height: 100%; object-fit: contain; background: white; }
