.pagination { display: flex; justify-content: center; align-items: center; flex-wrap: wrap; gap: 8px 12px; margin-top: 14px; font-size: .84rem; }
.pagination button { min-height: 52px; padding: 6px 12px; border: 1px solid var(--line); border-radius: 10px; background: var(--raised); }

.compare-bar {
