      const rating = /후기평점\s*(\d+(?:\.\d+)?)\s*점/.exec(clean(card.querySelector('.section--itemcard_info_score')));
      const review = /^후기\s*([\d,]+)$/.exec(clean(card.querySelector('.text--reviewcnt')));
      return {id,title,price:clean(card.querySelector('.text--price_seller')),
        productRating:rating?.[1],reviewCount:review?.[1],
        image:image(card.querySelector('img.image--itemcard')),shippingText:delivery(card),
        seller:clean(card.querySelector('.link--shop')).replace(/^판매자\s*/,''),
        sponsored:/광고/.test(clean(card.querySelector('.area--itemcard_title'))) || !!card.querySelector('.button--ad'),url:C.canonicalURL('auction',id)};
    });
  }
  function eleven(doc) {
    return [...doc.querySelectorAll('.c-card-item')].slice(0,160).map(card => {
      const a = [...card.querySelectorAll('a')].find(n => C.productId('eleven',n.getAttribute('href')));
      const id = C.productId('eleven',a?.getAttribute('href'));
      const img = [...card.querySelectorAll('img')].find(n => /\/product\//.test(image(n)));
      const review = /^리뷰\s*\(([\d,]+)\)$/.exec(clean(card.querySelector('.c-starrate__review')));
      return {id,title:clean(a),price:clean(card.querySelector('.c-card-item__price')),image:image(img),
        reviewCount:review?.[1],
        shippingText:delivery(card,'.c-card-item__price-info'),sponsored:/광고표기/.test(clean(card)),url:C.canonicalURL('eleven',id)};
    });
  }
  function extract(id, doc) {
    const parser = {lotteon,hmall,gmarket,auction,eleven,gsshop,cj,ohou,himart,hns,ssg}[id];
    if (!parser || !doc) return {products:[],state:'error',message:'지원하지 않는 사이트입니다.'};
    const result = C.normalizeList(parser(doc),id);
    if (result.products.length) return {products:result.products,state:'ready',observedAt:new Date().toISOString()};
    const visible = (doc.body?.innerText || doc.body?.textContent || '').replace(/\s+/g,' ');
    if (/검색[된\s]*결과[가\s]*(?:없|존재하지)|상품[이\s]*(?:없습니다|존재하지)|일치하는 상품이 없/.test(visible)) return {products:[],state:'ready'};
    return {products:[],state:'unavailable',message:'사이트에서 상품 정보를 읽지 못했습니다. 원래 사이트에서 검색할 수 있습니다.'};
  }
  function inertHTML(html) {
    // DOMParser documents must not initiate image/iframe/style requests while reading metadata.
    return String(html).replace(/<base\b[^>]*>|<link\b[^>]*>/gi,'')
      .replace(/<style\b[^>]*>[\s\S]*?<\/style\s*>/gi,'')
      .replace(/(\s)(src|srcset|poster)\s*=/gi, '$1data-rivo-$2=');
  }
  return Object.freeze({ extract, inertHTML });
});

