    if(p.image){const img=node('img');img.alt='';img.loading='lazy';img.decoding='async';img.referrerPolicy='no-referrer';img.src=p.image;img.addEventListener('error',()=>picture.classList.add('no-image'),{once:true});picture.append(img);}else picture.classList.add('no-image');
    const body=node('div','card-body');
    const labels=[C.source(p.source).name];
    if(p.sponsored)labels.push('광고');
    if(p.availability==='out')labels.push('품절');
    const title=node('h3'),price=node('div','product-price');
    title.append(button(p.title,'card-open',()=>openOriginal(p)));
    if(p.price===null)price.append(node('strong','','가격 미확인'));else price.append(node('strong','',p.price.toLocaleString('ko-KR')),node('small','','원'));
    if(p.price!==null&&p.priceKind!=='표시 가격')price.append(node('span','price-kind',p.priceKind));
    body.append(title,node('p','small',labels.join(' · ')),price);
