    voiceResult(value){$('query').value=C.text(value,100);updateSearchButton();$('query').focus();announce('검색어를 확인한 뒤 검색을 눌러 주세요.');},
    nativeMessage(value){announce(C.text(value,250));},
    suspend(){if(store.busy()){send('cancel',{requestId});store.cancel();render();announce('검색을 중지했습니다. 다시 검색할 수 있습니다.');}},
    snapshot(){return {mode:'retailer-direct-v1',requestId,query:searchedQuery,count:store.products().length,busy:store.busy(),sources:Object.fromEntries(store.statuses()),selected:selected.size,products:store.products()};}
  });
  new ResizeObserver(fitComparisonSpace).observe($('compare-bar'));
